EQUIVALENT = {
 "N8": "overlapping layers: the up-front check of the evidence outputs against the inputs, and the same check inside stage(); removing ONE leaves the other. Removing BOTH together was tried by hand and four CLI tests failed, so the layers are pinned",
 "H11": "overlapping layers (up-front output check, per-file EXISTS at write time, and rollback of the private file); removing ONE leaves the other. Removing the whole set together WAS tried by hand and the CLI tests failed, so the layers are pinned",
 "P10": "overlapping layers (up-front both-outputs-required check, the per-file output check, and rollback); removing ONE leaves the other. Removing the whole set together WAS tried by hand and the CLI tests failed, so the layers are pinned",
 "Q14": "overlapping layers: the up-front existence check (H11/P12) and the rollback of earlier outputs; removing ONE leaves the other. Removing BOTH together was tried by hand and the CLI tests failed, so the layers are pinned",
 "P12": "overlapping layers (lstat-based precheck is backed by the exclusive hard-link EXISTS and rollback); removing ONE leaves the other. Removing the whole set together WAS tried by hand and the CLI tests failed, so the layers are pinned",
 "P7": "overlapping layers (stat size check and the bounded read length check); removing both together WAS tried by hand and the size test failed",
 "G4": "overlapping guards: the reserved-name check, the string-unit check on the benefit path, and the string/hasOwn test inside unitInfo each stop a prototype or array unit; removing ONE leaves the others (the array-unit test pins the end result). Removing all of them at once was tried by auditor 6 and by the author: the tests fail",
 "N2": "overlapping guards, see G4",
 "B10": "roundTripPreview only ever sets task states of the chosen case, so the scope guard is unreachable defence-in-depth",
}
ONLY = sys.argv[sys.argv.index("--only") + 1].split(",") if "--only" in sys.argv else None
if ONLY: M = [m for m in M if m[0].split()[0] in ONLY]
if "--list" in sys.argv:
    print(len(M), "mutations"); sys.exit(0)
survivors, killed, equiv = [], [], []
for mid, rel, old, new in M:
    src = (ROOT / rel).read_text(encoding="utf-8")
    if src.count(old) != 1:
        print(f"SETUP-ERROR {mid}: pattern found {src.count(old)} times in {rel}"); survivors.append((mid, "setup")); continue
    with tempfile.TemporaryDirectory() as tmp:
        dst = pathlib.Path(tmp) / "r"; shutil.copytree(ROOT, dst, ignore=shutil.ignore_patterns(".git", "node_modules", "results"))
        (dst / rel).write_text(src.replace(old, new), encoding="utf-8")
        r = subprocess.run(["node", "scripts/run-all.cjs"], cwd=dst, capture_output=True, text=True)
        short = mid.split()[0]
        if r.returncode != 0: killed.append((mid, "")); print("killed   " + mid)
        elif short in EQUIVALENT: equiv.append(mid); print("equivalent " + mid + "  [" + EQUIVALENT[short] + "]")
        else: survivors.append((mid, "")); print("SURVIVED " + mid)
print(f"\n{len(killed)} killed, {len(equiv)} reviewed-equivalent, {len(survivors)} SURVIVED of {len(M)}")
sys.exit(1 if survivors else 0)
